<script setup lang="ts">
import {computed,ref} from 'vue';
import type {ExecutionPlan,ExecutionEvidence} from '../executionTypes';
import type {SystemDesign} from '../systemTypes';
import type {TypedValue} from '../behaviorTypes';
import {stockScenario,multiCommandScenario,messageScenario,editableScenario,workflowScenarioStep,ownerCommandStep,scenarioStatuses,type SharedScenario,type SharedStep} from '../systemScenario';
import {api,APIError} from '../api';
import {useWorkspaceDraft} from '../composables/useWorkspaceDraft';
import {useActionFeedback} from '../composables/useNotifications';
import TypedValueEditor from './TypedValueEditor.vue';
import {workflowContracts} from '../workflowTypes';
import SystemWorkflowStepEditor from './SystemWorkflowStepEditor.vue';
import SystemMessageStepEditor from './SystemMessageStepEditor.vue';
import DraftStatus from './DraftStatus.vue';
const props=defineProps<{plan:ExecutionPlan;design:SystemDesign}>();
const emit=defineEmits<{result:[ExecutionEvidence]}>();
const acceptanceCases=ref<{name:string;description:string;scenario:SharedScenario}[]>([]),selectedCase=ref(-1);
const scenario=ref<SharedScenario>({name:'New shared scenario',steps:[],expected:[]});
const signature=ref(JSON.stringify(props.plan));
const recovery=useWorkspaceDraft('system-scenario-'+props.design.id,{scenario,signature});
const stale=computed(()=>signature.value!==JSON.stringify(props.plan));
const owners=computed(()=>props.plan.tasks.filter(t=>t.state));
const contracts=computed(()=>[...(props.plan.workflows||[]).flatMap(f=>workflowContracts(f.lock.workflow)),...props.plan.tasks.flatMap(t=>t.state?[...t.state.machine.machine.dataContracts,...t.state.machine.machine.commands.flatMap(c=>c.decision.packages.flatMap(p=>p.package.dataContracts||[]))]:t.bundle.packages.flatMap(p=>p.package.dataContracts||[]))]);
const busy=ref(''),error=ref(''),notice=ref('');useActionFeedback('Shared scenario',busy,notice,error);
const name=(id:string)=>props.plan.tasks.find(t=>t.id===id)?.name||id;
async function loadAcceptance(){if(busy.value)return;busy.value='Loading M1 acceptance scenarios';error.value='';try{const cases=await api<typeof acceptanceCases.value>('/systems/m1-scenarios','POST',{design:props.design});acceptanceCases.value=cases;selectedCase.value=0;chooseAcceptance();}catch(e){error.value=(e as Error).message;}finally{busy.value='';}}
function chooseAcceptance(){const selected=acceptanceCases.value[selectedCase.value];if(selected){scenario.value=editableScenario(selected.scenario);signature.value=JSON.stringify(props.plan);}}
function addWorkflow(kind:'workflow_start'|'workflow_event'|'workflow_deliver'|'workflow_retry'|'workflow_restart'){const previous=[...scenario.value.steps].reverse().find(s=>s.kind==='workflow_start');scenario.value.steps.push(workflowScenarioStep(props.plan,kind,kind==='workflow_start'?'workflow'+(scenario.value.steps.length+1):previous?.workflow?.instanceId||'workflow1'));}
function addWorkflowExpectation(instanceId:string){(scenario.value.expectedWorkflows??=[]).push({instanceId,status:'waiting',outcome:'',activeTaskNode:'',variables:{},outputs:{}});}
function expectedWorkflow(instanceId:string){const step=scenario.value.steps.find(s=>s.kind==='workflow_start'&&s.workflow?.instanceId===instanceId);return props.plan.workflows?.find(f=>f.id===step?.workflow?.workflowId)?.lock.workflow;}
const workflowInstances=computed(()=>[...new Set(scenario.value.steps.filter(s=>s.kind==='workflow_start').map(s=>s.workflow!.instanceId))]);
function reset(){scenario.value={name:'New shared scenario',steps:[],expected:[]};signature.value=JSON.stringify(props.plan);}
function example(multi:boolean|'messages'=false){try{scenario.value=multi==='messages'?messageScenario(props.plan):multi?multiCommandScenario(props.plan):stockScenario(props.plan);signature.value=JSON.stringify(props.plan);error.value='';}catch(e){error.value=(e as Error).message;}}
function add(){const byTask=new Map<string,Record<string,TypedValue>>();for(const p of props.plan.inputs){if(!byTask.has(p.taskId))byTask.set(p.taskId,{});}
 scenario.value.steps.push({kind:'invoke',inputs:[...byTask].map(([taskId,values])=>({taskId,values})),calls:owners.value.map(t=>({taskId:t.id,commandId:'request'+(scenario.value.steps.length+1),expectedRevision:0,fault:''})),expectedStatuses:{}});}
function command(){const owner=owners.value[0];if(owner?.state)scenario.value.steps.push(ownerCommandStep(props.plan,owner.id,owner.state.machine.machine.commands[0]!.name,'command'+(scenario.value.steps.length+1)));}
function changeCommand(s:SharedStep,taskId:string,command?:string){const task=owners.value.find(t=>t.id===taskId);if(!task?.state)return;Object.assign(s,ownerCommandStep(props.plan,taskId,command||task.state.machine.machine.commands[0]!.name,s.calls?.[0]?.commandId||'command1'));}
function inputPorts(s:SharedStep,taskId:string){return s.kind==='command'?(owners.value.find(t=>t.id===taskId)?.state?.machine.machine.commands.find(c=>c.name===s.calls?.[0]?.command)?.inputs||[]):props.plan.inputs.filter(p=>p.taskId===taskId);}
function transport(kind:'dispatch'|'deliver'|'retry'|'broker_restart'){const c=props.plan.channels?.[0];if(!c)return;scenario.value.steps.push({kind,message:{channelId:c.id,...(kind==='dispatch'?{routeId:c.model.model.routes[0]?.id,sourceCommandId:'',alias:'message'+(scenario.value.steps.length+1),expectedRevision:0}:kind==='broker_restart'?{}:{alias:'',fault:''})},expectedStatuses:{}});}
function messageExpectation(){const c=props.plan.channels?.[0];if(c)(scenario.value.expectedMessages??=[]).push({channelId:c.id,name:'',status:'pending',attempts:0});}
function restart(){if(owners.value[0])scenario.value.steps.push({kind:'restart',taskId:owners.value[0].id,expectedStatuses:{}});}
function move(i:number,delta:number){const j=i+delta;if(j<0||j>=scenario.value.steps.length)return;[scenario.value.steps[i],scenario.value.steps[j]]=[scenario.value.steps[j]!,scenario.value.steps[i]!];}
function expectation(id:string){const t=owners.value.find(t=>t.id===id);if(!t?.state)return;scenario.value.expected.push({taskId:id,state:JSON.parse(JSON.stringify(Object.fromEntries(t.state.machine.machine.state.map(s=>[s.name,s.initial])))),revision:0,receipts:0,effects:0});}
function setStatus(s:SharedStep,id:string,event:Event){const value=(event.target as HTMLSelectElement).value;s.expectedStatuses??={};if(value)s.expectedStatuses[id]=value;else delete s.expectedStatuses[id];}
async function run(){if(busy.value||stale.value)return;busy.value='Running shared scenario';error.value='';notice.value='';const snapshot=JSON.stringify({design:props.design,scenario:scenario.value});try{await recovery.ready;const result=await api<ExecutionEvidence>('/systems/execution/run','POST',JSON.parse(snapshot));emit('result',result);notice.value=result.report.scenario?.passed?'Declared scenario expectations passed':'Review scenario verdicts';}catch(e){error.value=(e as Error).message;if(e instanceof APIError)error.value+=' '+e.issues.map(i=>i.path+': '+i.message).join('; ');}finally{busy.value='';}}
</script>
<template>
<section class="scenario-editor" :inert="recovery.status.value==='loading'" :aria-busy="!!busy">
 <h3>Shared scenario</h3><p>State persists across these ordered steps within this run. Set expected revisions explicitly. This explores one interleaving, not every possible race.</p>
 <DraftStatus :draft="recovery"/><p v-if="stale" role="alert">The prepared graph changed. Reset or reload the example before editing this scenario.</p>
 <div class="actions"><button @click="reset" :disabled="!!busy">New empty scenario</button><button @click="example()" :disabled="!!busy">Load stock retry scenario</button><button @click="example(true)" :disabled="!!busy">Load multi-command scenario</button><button v-if="plan.channels?.length" @click="example('messages')" :disabled="!!busy">Load stock-to-ledger scenario</button><button v-if="plan.workflows?.length" @click="loadAcceptance" :disabled="!!busy">Load M1 acceptance suite</button></div>
 <label v-if="acceptanceCases.length">M1 acceptance scenario<select v-model.number="selectedCase" @change="chooseAcceptance" :disabled="!!busy"><option v-for="(c,i) in acceptanceCases" :key="c.name" :value="i">{{c.name}}</option></select><small>{{acceptanceCases[selectedCase]?.description}}</small></label>
 <fieldset :disabled="!!busy||stale"><label>Scenario name<input v-model="scenario.name"/></label>
 <div class="actions"><button @click="add" :disabled="scenario.steps.length>=64">Add graph invocation</button><button @click="command" :disabled="scenario.steps.length>=64">Add owner command</button><button @click="restart" :disabled="scenario.steps.length>=64">Add owner restart</button><template v-if="plan.channels?.length"><button v-for="kind in (['dispatch','deliver','retry','broker_restart'] as const)" :key="kind" @click="transport(kind)" :disabled="scenario.steps.length>=64">Add {{kind.replaceAll('_',' ')}}</button></template></div>
 <div v-if="plan.workflows?.length" class="actions"><button v-for="kind in (['workflow_start','workflow_event','workflow_deliver','workflow_retry','workflow_restart'] as const)" :key="kind" @click="addWorkflow(kind)" :disabled="scenario.steps.length>=64">Add {{kind.replaceAll('_',' ')}}</button></div>
 <article v-for="(s,i) in scenario.steps" :key="i"><h4>{{i+1}} · {{(s.message||s.workflow)?s.kind.replaceAll('_',' '):s.kind==='restart'?'Restart owner':s.kind==='command'?'Call owner command':'Invoke graph'}}</h4>
  <div class="actions"><button @click="move(i,-1)" :disabled="i===0">Move up</button><button @click="move(i,1)" :disabled="i===scenario.steps.length-1">Move down</button><button @click="scenario.steps.splice(i+1,0,JSON.parse(JSON.stringify(s)))" :disabled="scenario.steps.length>=64">Duplicate / retry</button><button @click="scenario.steps.splice(i,1)">Remove</button></div>
  <SystemWorkflowStepEditor v-if="s.workflow" :step="s" :plan="plan" :previous="scenario.steps.slice(0,i)"/><SystemMessageStepEditor v-else-if="s.message" :step="s" :plan="plan" :previous="scenario.steps.slice(0,i)"/><label v-else-if="s.kind==='restart'">Owner<select v-model="s.taskId" @change="s.expectedStatuses={}"><option v-for="t in owners" :key="t.id" :value="t.id">{{t.name}}</option></select></label>
  <template v-else><label v-if="s.kind==='command'">State owner<select :value="s.taskId" @change="changeCommand(s,($event.target as HTMLSelectElement).value)"><option v-for="t in owners" :key="t.id" :value="t.id">{{t.name}}</option></select></label><p v-if="s.kind==='command'">This step calls only this owner and records its response. It does not invoke graph links. Changing the owner or command resets its inputs, revision and expectations.</p><section v-for="call in s.calls" :key="call.taskId"><h5>{{name(call.taskId)}}</h5><label v-if="s.kind==='command'">Command *<select :value="call.command" @change="changeCommand(s,call.taskId,($event.target as HTMLSelectElement).value)"><option v-for="c in owners.find(t=>t.id===call.taskId)?.state?.machine.machine.commands||[]" :key="c.name">{{c.name}}</option></select></label><p v-else>Graph entry: {{owners.find(t=>t.id===call.taskId)?.state?.entryCommand||owners.find(t=>t.id===call.taskId)?.state?.machine.machine.commands[0]?.name}}</p><label>Command ID<input v-model="call.commandId" maxlength="64"/></label><label>Expected revision<input type="number" min="0" step="1" v-model.number="call.expectedRevision"/></label><label>Fault<select v-model="call.fault"><option value="">None</option><option value="before_commit">Before commit</option><option value="after_commit_before_reply">After commit, before reply</option></select></label></section>
   <section v-for="input in s.inputs" :key="input.taskId"><TypedValueEditor v-for="port in inputPorts(s,input.taskId)" :key="port.name" :model-value="input.values[port.name]" :type="port.type as any" :record-ref="port.recordRef" :contracts="contracts" :label="name(input.taskId)+' / '+port.name" @update:model-value="value=>{if(value)input.values[port.name]=value;else delete input.values[port.name]}"/></section>
  </template>
  <details v-if="!s.message&&!s.workflow"><summary>Expected task outcomes (optional)</summary><label v-for="t in (s.kind!=='invoke'?owners.filter(t=>t.id===s.taskId):plan.tasks)" :key="t.id">{{t.name}}<select :value="s.expectedStatuses?.[t.id]||''" @change="setStatus(s,t.id,$event)"><option value="">No assertion</option><option v-for="status in scenarioStatuses" :key="status">{{status}}</option></select></label></details>
 </article>
 <h4>Expected final state</h4><p>Enter expected values before running. New expectations start from the definition's initial state, never from observed results.</p><button v-for="t in owners.filter(t=>!scenario.expected.some(e=>e.taskId===t.id))" :key="t.id" @click="expectation(t.id)">Add expectation: {{t.name}}</button>
 <article v-for="(e,i) in scenario.expected" :key="e.taskId"><h5>{{name(e.taskId)}}</h5><label>Revision<input type="number" min="0" v-model.number="e.revision"/></label><label>Receipt count<input type="number" min="0" v-model.number="e.receipts"/></label><label>Effect count<input type="number" min="0" v-model.number="e.effects"/></label><TypedValueEditor v-for="slot in owners.find(t=>t.id===e.taskId)?.state?.machine.machine.state||[]" :key="slot.name" :model-value="e.state[slot.name]" :type="slot.type" :record-ref="slot.recordRef" :contracts="contracts" :label="slot.name" @update:model-value="value=>{if(value)e.state[slot.name]=value;else delete e.state[slot.name]}"/><button @click="scenario.expected.splice(i,1)">Remove expectation</button></article>
 <section v-if="plan.channels?.length"><h4>Expected final messages</h4><button @click="messageExpectation" :disabled="(scenario.expectedMessages?.length||0)>=32">Add message expectation</button><article v-for="(e,i) in scenario.expectedMessages||[]" :key="i"><label>Channel<select v-model="e.channelId"><option v-for="c in plan.channels" :key="c.id" :value="c.id">{{c.model.model.name}}</option></select></label><label>Message alias *<input v-model="e.name"/></label><label>Status<select v-model="e.status" @change="delete e.accepted;if(e.status==='absent')e.attempts=0"><option>absent</option><option>pending</option><option>acknowledged</option></select></label><label>Attempts *<input type="number" min="0" v-model.number="e.attempts" :disabled="e.status==='absent'"/></label><label v-if="e.status==='acknowledged'">Business acceptance<select :value="e.accepted===undefined?'':String(e.accepted)" @change="($event.target as HTMLSelectElement).value===''?delete e.accepted:e.accepted=($event.target as HTMLSelectElement).value==='true'"><option value="">No assertion</option><option value="true">Accepted</option><option value="false">Rejected</option></select></label><button @click="scenario.expectedMessages?.splice(i,1)">Remove expectation</button></article></section>
 <section v-if="plan.workflows?.length"><h4>Expected final workflows</h4><button v-for="id in workflowInstances.filter(id=>!scenario.expectedWorkflows?.some(e=>e.instanceId===id))" :key="id" @click="addWorkflowExpectation(id)">Add expectation: {{id}}</button><article v-for="(e,i) in scenario.expectedWorkflows||[]" :key="e.instanceId"><h5>{{e.instanceId}}</h5><label>Status *<select v-model="e.status"><option>waiting</option><option>completed</option><option>failed</option></select></label><label>Outcome (empty while waiting)<input v-model="e.outcome"/></label><label>Active task node<select v-model="e.activeTaskNode"><option value="">No active task</option><option v-for="n in expectedWorkflow(e.instanceId)?.nodes.filter(n=>n.task)||[]" :key="n.id" :value="n.id">{{n.name}}</option></select></label><details><summary>Variable and output assertions (optional fields)</summary><TypedValueEditor v-for="v in expectedWorkflow(e.instanceId)?.variables||[]" :key="v.name" :model-value="e.variables[v.name]" :type="v.type" :record-ref="v.recordRef" :contracts="contracts" :label="'Variable / '+v.name" @update:model-value="value=>{if(value)e.variables[v.name]=value;else delete e.variables[v.name]}"/><TypedValueEditor v-for="v in expectedWorkflow(e.instanceId)?.outputs||[]" :key="v.name" :model-value="e.outputs[v.name]" :type="v.type" :record-ref="v.recordRef" :contracts="contracts" :label="'Output / '+v.name" @update:model-value="value=>{if(value)e.outputs[v.name]=value;else delete e.outputs[v.name]}"/></details><button @click="scenario.expectedWorkflows?.splice(i,1)">Remove workflow expectation</button></article></section>
 <button @click="run" :disabled="!scenario.steps.length">Run shared scenario</button>
 </fieldset><p role="status">{{busy}}</p><p v-if="error" role="alert">{{error}}</p>
</section>
</template>
<style scoped>
.scenario-editor{margin:20px 0;min-width:0}.scenario-editor fieldset{min-width:0;border:1px solid #cbdce3;padding:12px;border-radius:8px}.scenario-editor article{border:1px solid #cbdce3;border-radius:8px;padding:14px;margin:12px 0;min-width:0}.scenario-editor label{display:grid;gap:5px;margin:8px 0;font-size:12px}.scenario-editor input,.scenario-editor select{min-width:0;width:100%;box-sizing:border-box;padding:8px;border:1px solid #cbdce3;border-radius:5px}.actions{display:flex;gap:6px;flex-wrap:wrap}.scenario-editor p{overflow-wrap:anywhere}
</style>
